def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(alt_sum, parity)] = set of products
    # parity 0: next element will be added (even index in subsequence)
    # parity 1: next element will be subtracted (odd index in subsequence)
    dp = {}

    for x in nums:
        current_updates = []

        # Option A: Start a new subsequence with x
        if x <= limit:
            current_updates.append( ((x, 1), x) ) # sum=x, next is parity 1 (odd index)

        # Option B: Append x to existing subsequences
        for (s, parity), products in dp.items():
            if parity == 1: # Current count is odd, next index is even -> add x
                next_s = s + x
                for p in products:
                    if p * x <= limit:
                        current_updates.append( ((next_s, 0), p * x) )
            else: # Current count is even, next index is odd -> subtract x
                next_s = s - x
                for p in products:
                    if p * x <= limit:
                        current_updates.append( ((next_s, 1), p * x) )

        for (state, prod) in current_updates:
            if state not in dp:
                dp[state] = set()
            dp[state].add(prod)

    ans = -1
    for (s, parity), products in dp.items():
        if s == k:
            if products:
                ans = max(ans, max(products))
    return ans
