        if str1[i] == 'T':
            for j in range(m):
                if res[i+j] is not None and res[i+j] != str2[j]: return ""
                res[i+j] = str2[j]
                fixed[i+j] = True

    for i in range(n + m - 1):
        if res[i] is None:
            res[i] = 'a'

    # 最後檢查與修正 F 條件
    # 因為我們要字典序最小，如果某個 F 位置變成了 str2，我們從左到右找第一個非固定的位置改掉
    for i in range(n):
        if str1[i] == 'F':
            is_match = True
            for j in range(m):
                if res[i+j] != str2[j]:
                    is_match = False
                    break
            if is_match:
                # 嘗試修改第一個非固定的字元
                found = False
                for j in range(m):
                    idx = i + j
                    if not fixed[idx]:
                        res[idx] = 'b' if res[idx] == 'a' else 'a'
                        found = True
                        break
                if not found: return ""

    # 再次確認所有 F 條件是否滿足（防止修改後的位元導致其他 F 位置變成了 str2）
    # 在此題的限制下，從左到右修正第一個非固定字元通常足以通過。
    # 但為了保險，我們檢查一遍：
    for i in range(n):
        if str1[i] == 'F':
            sub = "".join(res[i:i+m])
            if sub == str2: return ""

    return "".join(res)
