from typing import List

def shiftDistance(s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
    total_cost = 0
    for char_s, char_t in zip(s, t):
        start = ord(char_s) - ord('a')
        end = ord(char_t) - ord('a')

        # Cost to move forward (i -> i+1)
        # Since costs vary per character, we use Dijkstra-like logic or 
        # simply observe that at each step j, moving forward costs nextCost[j]
        # and moving backward costs previousCost[j].
        # However, the problem implies a path of operations.
        # Because we want "minimum total cost", this is a shortest path on a cycle graph 
        # where nodes are 0-25.

        # Precompute all-pairs shortest paths for the 26 letters
        dist = [[float('inf')] * 26 for _ in range(26)]
        for i in range(26):
            dist[i][i] = 0
            # Forward move: i -> (i+1)%26
            dist[i][(i + 1) % 26] = min(dist[i][(i + 1) % 26], nextCost[i])
            # Backward move: i -> (i-1)%26
            dist[i][(i - 1) % 26] = min(dist[i][(i - 1) % 26], previousCost[i])

        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        total_cost += dist[start][end]

    return int(total_cost)
