import math
from typing import List
from functools import reduce

def maxScore(nums: List[int]) -> int:
    def get_gcd(a, b):
        return math.gcd(a, b)

    def get_lcm(a, b):
        if a == 0 or b == 0: return 0
        return abs(a * b) // math.gcd(a, b)

    def calculate_score(arr):
        if not arr: return 0
        res_gcd = arr[0]
        res_lcm = arr[0]
        for i in range(1, len(arr)):
            res_gcd = get_gcd(res_gcd, arr[i])
            res_lcm = get_lcm(res_lcm, arr[i])
        return res_gcd * res_lcm

    # Case 0: Remove nothing
    max_score = calculate_score(nums)

    # Case 1: Remove exactly one element
    for i in range(len(nums)):
        current_arr = nums[:i] + nums[i+1:]
        if current_arr:
            max_score = max(max_score, calculate_score(current_arr))
        else:
            # Problem says factor score of empty array is 0
            max_score = max(max_score, 0)

    return max_score
