from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # 將每個 list 轉換為 set 以便計算交集中的不重複元素數量
    sets = [set(p) for p in properties]

    # 使用 Disjoint Set Union (DSU) 來管理連通分量
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # 建立圖的邊：若交集大小 >= k，則合併連通分量
    for i in range(n):
        for j in range(i + 1, n):
            if len(sets[i] & sets[j]) >= k:
                union(i, j)

    # 計算有多少個唯一的根節點（即連通分量的數量）
    count = 0
    for i in range(n):
        if parent[i] == i:
            count += 1
    return count
