from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    adj = [[] for _ in range(n)]

    # Pre-process unique elements to simplify intersection count
    unique_props = [set(p) for p in properties]

    for i in range(n):
        for j in range(i + 1, n):
            # Count common distinct integers
            if len(unique_props[i].intersection(unique_props[j])) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    count = 0
    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
    return count
