    # Since we only need the previous row/state, use 3D array or optimize space.
    # Given constraints and "speed", a 3D DP table [3][m][n] is efficient.
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # Initial state
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[1][0][0] = 0 # Use 1 neutralization on a negative cell to treat as 0
        dp[0][0][0] = val # Or don't use it and take the loss

    for k in range(3):
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0: continue

                res = -float('inf')
                # From Top
                if i > 0:
                    res = max(res, dp[k][i-1][j], dp[k-1][i-1][j] if k > 0 else -float('inf'))
                # From Left
                if j > 0:
                    res = max(res, dp[k][i][j-1], dp[k-1][i][j-1] if k > 0 else -float('inf'))

                current_coin = coins[i][j]
                if current_coin >= 0:
                    dp[k][i][j] = max(dp[k][i][j], res + current_coin)
                else:
                    # Option A: Don't neutralize (take the negative value)
                    dp[k][i][j] = max(dp[k][i][j], res + current_coin)
                    # Option B: Neutralize (treat as 0, requires k > 0)
                    if k > 0:
                        dp[k][i][j] = max(dp[k][i][j], res)

    return max(dp[k][m-1][n-1] for k in range(3))
