from typing import List

def minimumIncrements(nums: List[int], target: List[int]) -> int:
    # 預處理：找出每個目標數字是否已經有倍數在 nums 中
    # 因為 target 長度極小 (<=4)，我們可以直接對每個 target 做檢查
    n = len(nums)
    m = len(target)

    # 計算每個 nums[i] 到達最近的 target[j] 倍數需要的步數
    # cost[i][j] 表示要把 nums[i] 變成 target[j] 的倍數需要的次數
    costs = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            t = target[j]
            if nums[i] % t == 0:
                costs[i][j] = 0
            else:
                # 下一個倍數是 ((nums[i] // t) + 1) * t
                costs[i][j] = (nums[i] // t + 1) * t - nums[i]

    # 因為 target 長度極小且目標是「每個 target 至少有一個倍數」
    # 我們需要從 nums 中選出若干個數字，並分配給不同的 target
    # 這是最小權值完美匹配問題的變體（或簡單的狀態壓縮 DP）
    # 但因為 target 只有最多 4 個，且我們只需要滿足每個 target 有一個對應的 nums[i]
    # 我們可以直接用 BFS 或 遞迴 + 記憶化 來找出最少的操作數。

    # 因為題目要求「最小操作數」，且每次操作只能增加，
    # 其實是找一組映射：將 target 的每個元素分配給一個唯一的 nums[i]
    # 令 f(mask) 為滿足 mask 中已處理的 target 所需的最少次數。

    memo = {}

    def solve(mask, idx):
        if mask == (1 << m) - 1:
            return 0
        if idx == n:
            return float('inf')

        state = (mask, idx)
        if state in memo: return memo[state]

        # 選項 1：不使用 nums[idx] 來滿足任何 target
        res = solve(mask, idx + 1)

        # 選項 2：用 nums[idx] 去滿足某個還沒被滿足的 target j
        for j in range(m):
            if not (mask & (1 << j)):
                res = min(res, costs[idx][j] + solve(mask | (1 << j), idx + 1))

        memo[state] = res
        return res

    # 優化：因為 target 很少，我們其實只需要考慮對每個 target 選出最優的 nums[i]
    # 如果 target 有重複值，先去重。
    unique_targets = sorted(list(set(target)))
    m = len(unique_targets)

    # 重新計算 costs 基於 unique_targets
    costs = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            t = unique_targets[j]
            if nums[i] % t == 0:
                costs[i][j] = 0
            else:
                costs[i][j] = (nums[i] // t + 1) * t - nums[i]

    # 使用動態規劃：dp[mask] 是滿足 mask 中 target 的最小代價
    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    for i in range(n):
        for mask in range((1 << m) - 1, -1, -1):
            if dp[mask] == float('inf'): continue
            for j in range(m):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    if dp[new_mask] > dp[mask] + costs[i][j]:
                        dp[new_mask] = dp[mask] + costs[i][j]

    return dp[(1 << m) - 1]
```

