from typing import List
from collections import deque

def findSafeWalk(grid: List[List[int]], health: int) -> bool:
    rows, cols = len(grid), len(grid[0])
    # queue 儲存 (row, col, current_health)
    queue = deque([(0, 0, health - grid[0][0])])
    # visited 記錄每個座標達到時的最大剩餘生命，避免重複進入且效能較差的路徑
    visited = {(0, 0): health - grid[0][0]}

    while queue:
        r, c, h = queue.popleft()

        if h <= 0:
            continue
        if r == rows - 1 and c == cols - 1:
            return True

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                new_h = h - grid[nr][nc]
                # 如果新路徑的生命比之前到達該點的生命高，才繼續探索
                if new_h > visited.get((nr, nc), -1):
                    visited[(nr, nc)] = new_h
                    queue.append((nr, nc, new_h))

    return False
