        next_dp = [0] * n
        # Pre-calculate max of (dp[prev] + travelScore[prev][curr])
        # Since we want max over all prev, and stay/travel are independent:
        # next_dp[j] = max(dp[j] + stayScore[i][j], max_{p != j}(dp[p] + travelScore[p][j]))

        # Optimization: To do this in O(n^2) total per day, we just iterate all pairs.
        for curr in range(n):
            best_travel = 0
            for prev in range(n):
                if prev == curr:
                    score = dp[prev] + stayScore[i][curr]
                else:
                    score = dp[prev] + travelScore[prev][curr]
                if score > best_travel:
                    best_travel = score
            next_dp[curr] = best_travel
        dp = next_dp

    return max(dp)
