from collections import defaultdict

def maxAmount(initialCurrency, pairs1, rates1, pairs2, rates2):
    currs = {initialCurrency}
    for p in pairs1 + pairs2: currs.update(p)

    adj1 = defaultdict(dict)
    for (u, v), r in zip(pairs1, rates1):
        adj1[u][v] = max(adj1[u].get(v, 0), r)
        adj1[v][u] = max(adj1[v].get(u, 0), 1.0 / r)

    adj2 = defaultdict(dict)
    for (u, v), r in zip(pairs2, rates2):
        adj2[u][v] = max(adj2[u].get(v, 0), r)
        adj2[v][u] = max(adj2[v].get(u, 0), 1.0 / r)

    d1 = {c: 0.0 for c in currs}
    d1[initialCurrency] = 1.0
    for _ in range(len(currs)):
        for u in adj1:
            for v, r in adj1[u].items():
                if d1[u] * r > d1[v]: d1[v] = d1[u] * r

    ans = d1[initialCurrency]
    for start_node in currs:
        if d1[start_node] > 0:
            d2 = {c: 0.0 for c in currs}
            d2[start_node] = d1[start_node]
            for _ in range(len(currs)):
                for u in adj2:
                    for v, r in adj2[u].items():
                        if d2[u] * r > d2[v]: d2[v] = d2[u] * r
            ans = max(ans, d2[initialCurrency])
    return float(ans)
