import heapq

def minOperations(n: int, m: int):
    # Pre-calculate primes up to 10000 using a sieve
    limit = 10000
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if is_prime[p]:
            for i in range(p*p, limit + 1, p):
                is_prime[i] = False

    # Check if start or end are prime (invalid states)
    if is_prime[n] or is_prime[m]:
        return -1

    # Dijkstra's algorithm
    # pq stores: (total_cost, current_value)
    pq = [(0, n)]
    visited = {n: 0}

    while pq:
        cost, curr = heapq.heappop(pq)

        if curr == m:
            return cost

        if cost > visited.get(curr, float('inf')):
            continue

        # Try all possible next values by changing one digit
        s_curr = list(str(curr))
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # Option 1: Increase digit (if not 9)
            if digit < 9:
                next_val = int("".join(map(str, s_curr))) + (10 ** (len(s_curr) - 1 - i))
                # The problem says "increase it by 1", but we must ensure 
                # the number of digits stays the same and logic follows digit-wise change.
                # Actually, changing a digit by 1 is equivalent to adding/subtracting 10^k
                # while ensuring no carry over that changes digit count or violates constraints.

                # Correct interpretation: "Choose any digit... increase it by 1"
                # This means n -> n + 10^(position)
                new_n = curr + (10 ** (len(s_curr) - 1 - i))
                if new_n < limit and not is_prime[new_n] and len(str(new_n)) == len(str(m)):
                    new_cost = cost + new_n
                    if new_cost < visited.get(new_n, float('inf')):
                        visited[new_n] = new_cost
                        heapq.heappush(pq, (new_cost, new_n))

            # Option 2: Decrease digit (if not 0)
            if digit > 0:
                new_n = curr - (10 ** (len(s_curr) - 1 - i))
                if new_n >= 0 and new_n < limit and not is_prime[new_n] and len(str(new_n)) == len(str(m)):
                    new_cost = cost + new_n
                    if new_cost < visited.get(new_n, float('inf')):
                        visited[new_n] = new_cost
                        heapq.heappush(pq, (new_cost, new_n))

    return -1
