from typing import List
from collections import deque

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # Precompute shortest paths between all points (knight + pawns)
    all_pts = [[kx, ky]] + positions
    n = len(all_pts)
    dist = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0
        q = deque([i])
        while q:
            u = q.popleft()
            r, c = all_pts[u]
            for dr, dc in [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 50 and 0 <= nc < 50:
                    # Check if (nr, nc) is any of the points
                    for v in range(n):
                        if all_pts[v] == [nr, nc]:
                            if dist[i][v] == float('inf'):
                                dist[i][v] = dist[u][v] + 1 # This logic is wrong for BFS, need standard BFS
                # Correction: Standard BFS to find distance from all_pts[i] to all other points

    # Corrected BFS precomputation
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
        q = deque([i])
        while q:
            u = q.popleft()
            r, c = all_pts[u]
            for dr, dc in [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 50 and 0 <= nc < 50:
                    for v in range(n):
                        if all_pts[v] == [nr, nc] and dist[i][v] == float('inf'):
                            dist[i][v] = dist[i][u] + 1
                            q.append(v)

    memo = {}

    def solve(curr_idx: int, mask: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        state = (curr_idx, mask)
        if state in memo:
            return memo[state]

        # Alice wants to maximize, Bob wants to minimize
        # Turn is determined by number of bits set in mask
        turn_alice = (bin(mask).count('1') % 2 == 0)

        res = -float('inf') if turn_alice else float('inf')

        for i in range(n):
            if not (mask & (1 << i)):
                # The cost is the distance from current knight position to pawn i
                d = dist[curr_idx][i]
                val = d + solve(i, mask | (1 << i))
                if turn_alice:
                    res = max(res, val)
                else:
                    res = min(res, val)

        memo[state] = res
        return res

    # The first point is the knight's start position (index 0)
    # We need to find the distance from initial kx, ky to all pawns.
    # But the game starts with Alice choosing a pawn.
    # Actually, the current logic works because solve(0, 1<<0) would mean we already "visited" the start.
    # Let's refine: The knight is at index 0. Mask should only include captured pawns.

    memo = {}
    def solve_refined(curr_idx: int, mask: int) -> int:
        if mask == (1 << n) - 1: return 0
        state = (curr_idx, mask)
        if state in memo: return memo[state]

        turn_alice = (bin(mask).count('1') % 2 == 0)
        res = -float('inf') if turn_alice else float('inf')

        for i in range(1, n): # Pawns are indices 1 to n-1
            if not (mask & (1 << i)):
                d = dist[curr_idx][i]
                val = d + solve_refined(i, mask | (1 << i))
                if turn_alice: res = max(res, val)
                else: res = min(res, val)
        memo[state] = res
        return res

    # Initial call: knight is at 0, no pawns captured.
    # Wait, the mask should only track which PAWNS are captured.
    # Let's adjust indices: 0 is start, 1..n-1 are pawns.
    # The solve_refined(0, 0) will work perfectly.
    return solve_refined(0, 0)

