from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # Build a set of all possible prefixes
    prefixes = set()
    for w in words:
        for i in range(1, len(w) + 1):
            prefixes.add(w[:i])

    n = len(target)
    # dp[i] is the min strings to form target[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue
        # Try every possible prefix starting from current position
        for j in range(i + 1, n + 1):
            if target[i:j] in prefixes:
                dp[j] = min(dp[j], dp[i] + 1)

    return dp[n] if dp[n] != float('inf') else -1
