from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # offline_until stores the timestamp when a user will be back online
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp to ensure chronological processing
    # If timestamps are equal, OFFLINE must come before MESSAGE
    # We use a custom sort key: (timestamp, type_priority)
    # Type priority: OFFLINE = 0, MESSAGE = 1
    sorted_events = sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

    for event in sorted_events:
        etype, ts_str, content = event
        ts = int(ts_str)

        if etype == "OFFLINE":
            user_id = int(content.split()[0].replace("id", ""))
            offline_until[user_id] = ts + 60
        else:
            tokens = content.split()
            for token in tokens:
                if token == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif token == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= ts:
                            mentions[i] += 1
                else:
                    # Extract number from idX
                    user_id = int(token.replace("id", ""))
                    mentions[user_id] += 1

    return mentions
