from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # status[i] stores the timestamp when user i will come back online. 
    # If 0, they are currently online.
    status = [0] * numberOfUsers

    # Sort events by timestamp to ensure chronological order.
    # If timestamps are equal, OFFLINE events must be processed before MESSAGE events.
    # We can use a tuple (timestamp, type_priority) for sorting.
    # Since "OFFLINE" comes first alphabetically, but we want it to process 
    # BEFORE "MESSAGE", we assign priority: OFFLINE = 0, MESSAGE = 1.
    sorted_events = []
    for e in events:
        priority = 0 if e[0] == "OFFLINE" else 1
        sorted_events.append((int(e[1]), priority, e))

    sorted_events.sort()

    for _, _, event in sorted_events:
        etype = event[0]

        if etype == "OFFLINE":
            user_id = int(event[2][2:]) # Extract number from "idX"
            status[user_id] = int(event[1]) + 60

        elif etype == "MESSAGE":
            content = event[2]
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                current_time = int(event[1])
                for i in range(numberOfUsers):
                    if status[i] <= current_time:
                        mentions[i] += 1
            else:
                # Parse mentions like "id1 id0"
                tokens = content.split()
                for token in tokens:
                    if token.startswith("id"):
                        user_id = int(token[2:])
                        mentions[user_id] += 1

    return mentions
