from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    # status[i] stores the timestamp when user i will come back online. 
    # If 0, it means they are currently online.
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp to ensure chronological processing
    # If timestamps are equal, OFFLINE must be processed before MESSAGE
    sorted_events = sorted(events, key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

    for event in sorted_events:
        etype = event[0]
        timestamp = int(event[1])
        content = event[2]

        if etype == "OFFLINE":
            user_id = int(content.split(' ')[1].replace("id", "")) # Handle cases like "id0" or just "0"
            # The problem says id_i is provided, but input format implies content might be "id_i" 
            # based on the description "OFFLINE, timestamp_i, id_i".
            # Let's refine: usually it's exactly "id_i", if not just the number.
            uid = int(content.replace("id", ""))
            offline_until[uid] = timestamp + 60

        elif etype == "MESSAGE":
            if content == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif content == "HERE":
                for i in range(numberOfUsers):
                    if offline_until[i] <= timestamp:
                        mentions[i] += 1
            else:
                tokens = content.split()
                for token in tokens:
                    if token.startswith("id"):
                        uid = int(token[2:])
                        mentions[uid] += 1
                    else:
                        # This handles cases where the input might just be the number without "id"
                        uid = int(token)
                        mentions[uid] += 1

    return mentions
