def longestPalindrome(s: str, t: str) -> int:
    n, m = len(s), len(t)
    res = 0
    # Precompute all possible palindromes from substrings of s and t
    # Since lengths are small (30), we can iterate all pairs.
    for i in range(n + 1):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            for k in range(m + 1):
                for l in range(k, m + 1):
                    combined = sub_s + t[k:l]
                    # Check if combined is palindrome
                    if combined == combined[::-1]:
                        res = max(res, len(combined))
    return res
